mapper.update:

			/*updateMasterWmGrWarehousingPopList */
			UPDATE ICOMIVDT IVDT SET 
                        IVDT.WMS_GR_QTY = 0, 
                        IVDT.WMS_GR_DATE = '', 
                        IVDT.WMS_GR_USER_ID = '',
                        IVDT.WMS_GR_DEL_DATE = SYSDATE,
                        IVDT.WMS_GR_DEL_USER_ID = #{USER_ID} 
             WHERE IVDT.INV_NO = #{INV_NO}      
                AND IVDT.BUYER = #{BUYER}      
               AND IVDT.PO_NO = #{PO_NO}       
              AND IVDT.STATUS <> 'D'


			/*updateMasterWmGrWarehousingPopList_v2 */
			UPDATE ICOMIVDT IVDT SET 
                        IVDT.WMS_GR_QTY = 0, 
                        IVDT.WMS_GR_DATE = '', 
                        IVDT.WMS_GR_USER_ID = '',
                        IVDT.WMS_GR_DEL_DATE = SYSDATE,
                        IVDT.WMS_GR_DEL_USER_ID = #{USER_ID},
                        IVDT.DELIVERY_DATE = '',
                        IVDT.DELIVERY_QTY = 0 
             WHERE IVDT.INV_NO = #{INV_NO}      
                AND IVDT.BUYER = #{BUYER}      
               AND IVDT.PO_NO = #{PO_NO}       
              AND IVDT.STATUS <> 'D'


			/* updateMasterWmGrWarehousingHubGrDel */
			UPDATE	HUBIVDT HUB
			SET		HUB.STATUS = 'D',
					HUB.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
					HUB.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
					HUB.CHANGE_USER_ID = #{USER_ID}
			WHERE	HUB.BUYER = #{BUYER}
			AND		HUB.S_INV_NO = #{INV_NO}
			AND		HUB.PO_NO = #{PO_NO}
            AND		HUB.STATUS <> 'D'


			/* updateMasterWmGrWarehousingHubIvDel */
			UPDATE	HUBIVDT HUB
			SET		HUB.STATUS = 'R',
					HUB.HUB_IV_QTY = 0,
					HUB.HUB_IV_DATE = NULL,
					HUB.HUB_IV_CREATE_DATE = NULL,
					HUB.HUB_IV_USER_ID = NULL,
					HUB.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
					HUB.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
					HUB.CHANGE_USER_ID = #{USER_ID}
			WHERE	HUB.BUYER = #{BUYER}
			AND		HUB.S_INV_NO = #{INV_NO}
			AND		HUB.PO_NO = #{PO_NO}
            AND		HUB.STATUS <> 'D'
            AND		NVL(HUB.HUB_IV_QTY,0) > 0
